// One search finds every open Renovate PR across the account, private repos included.
// Both repos set labels: ["dependencies"] in renovate.json, so the label is the marker.
const found = $input.first().json;
const items = found.items ?? [];

return items.map((pullRequest) => {
  const [owner, repository] = pullRequest.repository_url.split('/').slice(-2);
  return {
    json: {
      owner,
      repository,
      number: pullRequest.number,
      title: pullRequest.title,
      createdAt: pullRequest.created_at,
      link: pullRequest.html_url,
      // The search result carries no mergeable state; the PR endpoint does.
      detailUrl: pullRequest.repository_url + '/pulls/' + pullRequest.number,
    },
  };
});

const listed = $('List Renovate PRs').all().map((item) => item.json);
const details = $input.all();

// What GitHub's mergeable_state means, in words worth reading in a mail.
const states = {
  clean: { label: 'ready to merge', rank: 3 },
  behind: { label: 'behind main, rebasing', rank: 3 },
  blocked: { label: 'blocked by a required check or review', rank: 2 },
  unstable: { label: 'checks failing', rank: 1 },
  dirty: { label: 'CONFLICT, needs a resolution', rank: 0 },
  unknown: { label: 'GitHub still computing', rank: 3 },
};

const rows = [];
for (let index = 0; index < listed.length; index++) {
  const pullRequest = listed[index];
  const detail = details[index]?.json ?? {};
  const state = states[detail.mergeable_state] ?? { label: detail.mergeable_state ?? 'unknown', rank: 2 };
  const ageDays = Math.floor((Date.now() - new Date(pullRequest.createdAt).getTime()) / 86400000);
  rows.push({
    repository: pullRequest.owner + '/' + pullRequest.repository,
    number: pullRequest.number,
    title: pullRequest.title,
    state: detail.draft ? 'draft' : state.label,
    rank: detail.draft ? 2 : state.rank,
    ageDays,
    link: pullRequest.link,
  });
}

// Worst first, then oldest: whatever needs a person should be at the top.
rows.sort((a, b) => a.rank - b.rank || b.ageDays - a.ageDays);

const conflicted = rows.filter((row) => row.rank === 0).length;
const failing = rows.filter((row) => row.rank === 1).length;
const stale = rows.filter((row) => row.ageDays >= 7).length;

const subject = rows.length === 0
  ? 'Renovate \u2014 nothing open'
  : 'Renovate \u2014 ' + rows.length + ' open' +
    (conflicted ? ', ' + conflicted + ' conflicted' : '') +
    (failing ? ', ' + failing + ' failing' : '');

function escapeHtml(text) {
  const replacements = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  return String(text).replace(/[&<>"']/g, (character) => replacements[character]);
}

// Inline styles only: mail clients strip stylesheets.
const tableStyle = 'border-collapse:collapse;font:14px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif';
const headStyle = 'text-align:left;padding:6px 10px;border-bottom:2px solid #d0d0d0;font-weight:600';
const cellStyle = 'padding:6px 10px;border-bottom:1px solid #ececec;vertical-align:top';
const warnStyle = cellStyle + ';background:#fff6e5';

const htmlRows = rows.map((row) => {
  const style = row.rank <= 1 ? warnStyle : cellStyle;
  return '<tr>' +
    '<td style="' + style + ';white-space:nowrap">' + escapeHtml(row.repository) + '</td>' +
    '<td style="' + style + ';white-space:nowrap"><a href="' + row.link + '">#' + row.number + '</a></td>' +
    '<td style="' + style + '">' + escapeHtml(row.title) + '</td>' +
    '<td style="' + style + '">' + escapeHtml(row.state) + '</td>' +
    '<td style="' + style + ';text-align:right;white-space:nowrap">' + row.ageDays + 'd</td></tr>';
}).join('');

const headline = rows.length === 0
  ? 'No open dependency pull requests. Renovate has merged everything it could.'
  : rows.length + ' open' +
    (conflicted ? ' \u00b7 ' + conflicted + ' conflicted' : '') +
    (failing ? ' \u00b7 ' + failing + ' with failing checks' : '') +
    (stale ? ' \u00b7 ' + stale + ' older than a week' : '');

const html = '<div style="font:14px -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#222">' +
  '<p style="margin:0 0 12px">' + escapeHtml(headline) + '</p>' +
  (rows.length
    ? '<table style="' + tableStyle + '"><thead><tr>' +
      '<th style="' + headStyle + '">Repo</th><th style="' + headStyle + '">PR</th>' +
      '<th style="' + headStyle + '">Update</th><th style="' + headStyle + '">State</th>' +
      '<th style="' + headStyle + ';text-align:right">Age</th></tr></thead><tbody>' + htmlRows + '</tbody></table>'
    : '') +
  '</div>';

// Plain-text fallback, for clients that drop the HTML part.
const content = [
  headline,
  '',
  ...rows.map((row) => '  ' + row.repository + ' #' + row.number + '  ' + row.state +
    '  (' + row.ageDays + 'd)  ' + row.title),
].join('\n');

return [{ json: { subject, content, html } }];
